def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [
        fmt([5]), fmt([7, 7, 7]), fmt([1, 2]), fmt([2, 9, 4, 4, 6]), fmt([3, -1, 2, 2]),
        fmt([-5, -5]), fmt([0, 10, 0, 10]), fmt([-3, 4, 0]),
    ]
    for n in (2, 3, 4, 5, 6, 8):
        for _ in range(4):
            lo = rng.choice([-6, 0, 3])
            tests.append(fmt([rng.randint(lo, lo + 8) for _ in range(n)]))
    N = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([10**9] * (N - 1) + [-10**9]))
    tests.append(fmt([-10**9] * (N - 1) + [10**9]))
    tests.append(fmt([rng.choice([-10**9, 10**9]) for _ in range(N)]))
    return tests
